def solve(gi):
    H,W=len(gi),len(gi[0])
    tw={(i,j) for i,r in enumerate(gi) for j,x in enumerate(r) if x==2}
    th={(i,j) for i,r in enumerate(gi) for j,x in enumerate(r) if x==3}
    bgc=Counter(x for r in gi for x in r).most_common(1)[0][0]
    def free(i,j): return 0<=i<H and 0<=j<W and gi[i][j]==bgc
    dist={}; q=deque()
    for s in sorted(tw): dist[s]=0; q.append(s)
    while q:
        c=q.popleft(); i,j=c
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(i+di,j+dj)
            if free(n[0],n[1]) and n not in dist:
                dist[n]=dist[c]+1; q.append(n)
    goals=[n for g in th for n in ((g[0]-1,g[1]),(g[0]+1,g[1]),(g[0],g[1]-1),(g[0],g[1]+1)) if free(*n)]
    dgo=min(dist.get(g,999) for g in goals)
    out=[r[:] for r in gi]
    # choose goal with fewest ties / deterministic: prefer one that makes path monotone? Just take first with min
    start=goals[0] if all(dist[g]==dgo for g in goals) else min(goals,key=lambda g:(dist[g],g))
    cur=start; path={cur}
    while dist[cur]>0:
        cands=[prev for prev in ((cur[0]-1,cur[1]),(cur[0]+1,cur[1]),(cur[0],cur[1]-1),(cur[0],cur[1]+1)) if prev in dist and dist[prev]==dist[cur]-1]
        cur=cands[0]; path.add(cur)
    for cell in path-tw-th:
