    th=[(i,j) for i,r in enumerate(gi) for j,x in enumerate(r) if x==3]

    # Dijkstra over (cell, last_dir); cost = (turns, length)
    dist={(s,DIRS[0]):(0,0) for s in tw}
    par={}
    heap=[]
    for s in tw:
        heapq.heappush(heap,(dist[(s,DIRS[0])], s, DIRS[0]))
    while heap:
        _,c,last=heapq.heappop(heap)
        d,b=dist.get((c,last),(999,999))
        for di,dj in DIRS:
            n=(c[0]+di,c[1]+dj)
            if not free(*n): continue
            nb=b+(1 if (di,dj)!=last else 0)
            nk=((d if True else 0)+nb, d+1)
            key=(nk, c, di, dj, b)
            if (nk[0], nk[1]) < (dist.get((n,(di,dj)),(999,999))[0], dist.get((n,(di,dj)),(999,999))[1]):
                dist[(n,(di,dj))]=(nk); par[n]=(c,last)
                heapq.heappush(heap, ((nk[0],nk[1]), n, (di,dj)))
    best=None; tgt=None
    for g in th:
        for n in ((g[0]+1,g[1]),(g[0]-1,g[1]),(g[0],g[1]+1),(g[0],g[1]-1)):
            for ld in DIRS:
                if (n,ld) in dist and (best is None or dist[(n,ld)][0]<best[0] or (dist[(n,ld)][0]==best[0] and dist[(n,ld)][1]<best[1])):
                    best=dist[(n,ld)]; tgt=n
    path=[];cur=tgt
    while cur is not None and cur in par:
        path.append(cur); cur=par[cur][0]
    out=[r[:] for r in gi]
    for i,j in path:
        if gi[i][j]!=3: out[i][j]=3
    return out,path,best,tgt

